#!/usr/bin/env bash
set -euo pipefail
ACTION=${1:-apply};ROOT=${CLOUDIFF_V2_SOURCE_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)};PTR=/srv/cloudif/app-pointers/portal-current;STATE=/var/lib/cloudiff-v2/portal-admin-observability;SERVICE=cloudif-admin-portal.service
install -d -m 0700 "$STATE"
smoke(){ set -a;. /etc/cloudif/portal.env;set +a;local base="http://127.0.0.1:${CLOUDIF_PORTAL_PORT}";local headers=(-H 'Host: cloudiff.duckdns.org' -H 'X-Forwarded-Proto: https' -H 'X-authentik-username: v34-admin-gate' -H 'X-authentik-groups: CloudIF-Tenants-Admin');for _ in $(seq 1 60);do curl -fsS --max-time 2 "${headers[@]}" "$base/admin" >/tmp/v34-admin-page.html 2>/dev/null&&break;sleep .25;done;grep -q 'Administração do ambiente' /tmp/v34-admin-page.html;curl -fsS --max-time 3 "${headers[@]}" "$base/cloudiff/portal/api/admin-observability" | python3 -c 'import json,sys;x=json.load(sys.stdin);assert x.get("ok") is True and len(x.get("nodes",[]))>=3';local denied;denied=$(curl -sS -o /dev/null -w '%{http_code}' -H 'Host: cloudiff.duckdns.org' -H 'X-Forwarded-Proto: https' -H 'X-authentik-username: v34-user-gate' -H 'X-authentik-groups: CloudIF-Aluno' "$base/admin");[ "$denied" = 403 ];rm -f /tmp/v34-admin-page.html; }
apply(){ local current release;current=$(readlink -f "$PTR");[ -d "$current" ];[ -s "$STATE/previous" ]||printf '%s\n' "$current">"$STATE/previous";release=/srv/cloudif/app-releases/portal/v34-admin-observability;rm -rf "$release.new";cp -a "$current" "$release.new";patch -s -d "$release.new" -p0 < "$ROOT/compat/portal-admin-observability.patch";python3 -m py_compile "$release.new/cloudif-admin-portal.py";[ "$(sha256sum "$current/cloudif-admin-portal-base.py"|awk '{print $1}')" = "$(sha256sum "$release.new/cloudif-admin-portal-base.py"|awk '{print $1}')" ];rm -rf "$release";mv "$release.new" "$release";install -d -m 0755 /etc/systemd/system/cloudif-admin-portal.service.d;printf '[Service]\nEnvironmentFile=-/etc/cloudiff-v2/admin-observability.env\n' >/etc/systemd/system/cloudif-admin-portal.service.d/30-admin-observability.conf;ln -sfn "$release" "$PTR.new";mv -Tf "$PTR.new" "$PTR";systemctl daemon-reload;systemctl restart "$SERVICE";for _ in $(seq 1 50);do systemctl is-active --quiet "$SERVICE"&&break;sleep .2;done;systemctl is-active --quiet "$SERVICE";smoke;echo PORTAL_ADMIN_OBSERVABILITY=PASS; }
rollback(){ [ -s "$STATE/previous" ];local prev;prev=$(cat "$STATE/previous");[ -d "$prev" ];ln -sfn "$prev" "$PTR.new";mv -Tf "$PTR.new" "$PTR";rm -f /etc/systemd/system/cloudif-admin-portal.service.d/30-admin-observability.conf;systemctl daemon-reload;systemctl restart "$SERVICE";for _ in $(seq 1 50);do systemctl is-active --quiet "$SERVICE"&&break;sleep .2;done;systemctl is-active --quiet "$SERVICE";echo PORTAL_ADMIN_OBSERVABILITY_ROLLBACK=PASS; }
case "$ACTION" in apply)if ! apply;then rollback||true;exit 4;fi;;rollback)rollback;;smoke)smoke;;*)exit 2;;esac
